/**
 * A single content block inside a message payload, e.g. `{ type: 'input_text',
 * text: 'hello' }` or `{ type: 'output_text', text: 'hi' }`.
 */
export interface ContentBlock {
  type: string;
  text: string;
}

/**
 * The payload of a single rollout line. Only `type` is guaranteed to be present;
 * the remaining fields are populated depending on the record kind (session
 * metadata, event message, or response item).
 */
export interface RolloutPayload {
  type: string;
  /** Message role for `message` response items ('user' | 'assistant' | 'developer'). */
  role?: string;
