 * Helpers for reading and interpreting Codex JSONL transcript ("rollout") files.
 */

import { readFileSync } from 'fs';
import type { ContentBlock, RolloutLine } from './types';

/** Number of nanoseconds in a single millisecond. */
const NANOSECONDS_PER_MS = 1e6;

/**
 * Read a JSONL transcript file from disk and parse it into RolloutLine records.
 *
 * Each non-empty line of the file is parsed as a JSON object. Blank lines are
 * ignored so trailing newlines do not produce spurious records.
 *
 * @param filePath Absolute or relative path to the JSONL transcript file.
 * @returns One parsed RolloutLine per (non-empty) line in the file.
 */
export function readTranscript(filePath: string): RolloutLine[] {
  const raw = readFileSync(filePath, 'utf-8');
  return raw
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) => JSON.parse(line) as RolloutLine);
}

/**
 * Parse an ISO 8601 timestamp string into an integer number of nanoseconds.
 *
 * @param input An ISO 8601 timestamp string, or null/undefined/empty.
 * @returns The timestamp in nanoseconds, or null for null/undefined/empty input.
 */
export function parseTimestampToNs(input: string | null | undefined): number | null {
  if (input === null || input === undefined || input === '') {
    return null;
  }

  const ms = new Date(input).getTime();
  if (Number.isNaN(ms)) {
    return null;
  }

  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from a message content field.
 *
 * @param content An array of content blocks, a plain string, or undefined.
 * @returns The joined text (blocks joined with '\n'), the string unchanged, or ''.
 */
export function extractTextFromContent(
  content: ContentBlock[] | string | undefined,
): string {
  if (content === undefined) {
    return '';
  }

  if (typeof content === 'string') {
    return content;
  }

  return content
    .filter((block) => block != null && typeof block.text === 'string')
    .map((block) => block.text)
    .join('\n');
}

/**
 * Find the text of the most recent user message in the transcript.
 *
 * @param records The full list of rollout records.
 * @returns An object with the last user message text, or null if none exists.
 */
export function findLastUserPrompt(records: RolloutLine[]): { text: string } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const { payload } = records[i];
    if (payload?.role === 'user') {
      return { text: extractTextFromContent(payload.content) };
    }
  }
  return null;
}

/**
 * Return the records belonging to the most recent turn.
 *
 * A turn begins at the `task_started` event message and ends at the
 * `task_complete` event message (both inclusive).
 *
 * @param records The full list of rollout records.
 * @returns The slice of records for the most recent turn (empty if not found).
 */
export function getLastTurnRecords(records: RolloutLine[]): RolloutLine[] {
  const isEvent = (line: RolloutLine, eventType: string): boolean =>
    line.type === 'event_msg' && line.payload?.type === eventType;

  let startIdx = -1;
  for (let i = records.length - 1; i >= 0; i--) {
    if (isEvent(records[i], 'task_started')) {
      startIdx = i;
      break;
    }
  }

  if (startIdx === -1) {
    return [];
  }

  let completeIdx = -1;
  for (let i = records.length - 1; i >= startIdx; i--) {
    if (isEvent(records[i], 'task_complete')) {
      completeIdx = i;
      break;
    }
  }

  if (completeIdx === -1) {
    return [];
  }

  return records.slice(startIdx, completeIdx + 1);
}

/**
 * Locate the token_count event and return the aggregate token usage.
 *
 * @param records The full list of rollout records.
 * @returns The token usage counts, or null if no token_count event is present.
 */
export function getTokenUsage(
  records: RolloutLine[],
): { input_tokens: number; output_tokens: number; total_tokens: number } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const { payload } = records[i];
    if (records[i].type === 'event_msg' && payload?.type === 'token_count') {
      const info = payload.info ?? {};
      const usage = info.total_token_usage ?? info.last_token_usage ?? info ?? {};

      const inputTokens = Number(usage.input_tokens ?? 0);
      const outputTokens = Number(usage.output_tokens ?? 0);
      const totalTokens = Number(usage.total_tokens ?? inputTokens + outputTokens);

      return {
        input_tokens: inputTokens,
        output_tokens: outputTokens,
        total_tokens: totalTokens,
      };
    }
  }
  return null;
}

/**
 * Return the model name recorded in the session_meta record.
 *
 * @param records The full list of rollout records.
 * @returns The model name, or 'unknown' if none is recorded.
 */
export function getModel(records: RolloutLine[]): string {
  for (const record of records) {
    if (record.type === 'session_meta') {
      const { payload } = record;
      const model = payload?.model ?? payload?.info?.model;
      if (typeof model === 'string' && model.length > 0) {
        return model;
      }
      return 'unknown';
    }
  }
  return 'unknown';
}

/**
 * Return the session ID recorded in the session_meta record.
 *
 * @param records The full list of rollout records.
 * @returns The session ID string (empty string if none is recorded).
 */
export function getSessionId(records: RolloutLine[]): string {
  for (const record of records) {
    if (record.type === 'session_meta') {
      const id = record.payload?.id ?? record.payload?.info?.id;
      return typeof id === 'string' ? id : '';
    }
  }
  return '';
}

/**
 * Build a map from tool call_id to the tool's output string.
 *
 * @param records The full list of rollout records.
 * @returns A map from call_id to output string (empty if no tool outputs exist).
 */
export function buildToolResultMap(records: RolloutLine[]): Record<string, string> {
  const map: Record<string, string> = {};
  for (const record of records) {
    const { payload } = record;
    if (payload?.type === 'function_call_output' && payload.call_id != null) {
      map[payload.call_id] = coerceOutput(payload.output);
    }
  }
  return map;
}

/**
 * Coerce a function_call_output `output` field into a plain string.
 */
export function coerceOutput(output: unknown): string {
  if (output == null) {
    return '';
  }
  if (typeof output === 'string') {
    return output;
  }
  if (typeof output === 'object') {
    const obj = output as Record<string, unknown>;
    if (typeof obj.content === 'string') {
      return obj.content;
    }
    if (typeof obj.output === 'string') {
      return obj.output;
    }
    return JSON.stringify(output);
  }
  return String(output);
}
