   setStatus: (code: any, msg: any) => (rec.status = { code, msg }),\n      end: (e: any) => (rec.endArgs = e),\n    };\n    spans.push(rec);\n    return rec;\n  };\n  const trace = { info: { traceMetadata: {} } };\n  return {\n    init: jest.fn(),\n    startSpan: jest.fn((opts: any) => makeSpan(opts)),\n    flushTraces: jest.fn().mockResolvedValue(undefined),\n    SpanType: { LLM: 'LLM', TOOL: 'TOOL', AGENT: 'AGENT' },\n    SpanStatusCode: { ERROR: 'STATUS_CODE_ERROR', OK: 'STATUS_CODE_OK' },\n    TraceMetadataKey: { TRACE_SESSION: 'mlflow.trace.session', TRACE_USER: 'mlflow.trace.user' },\n    InMemoryTraceManager: { getInstance: () => ({ getTrace: () => trace }) },\n    __trace: trace,\n  };\n});\n\nimport * as core from '@mlflow/core';\nimport { processNotify, createChildSpans } from '../../src/tracing';\nimport {\n  getLastTurnRecords,\n  getModel,\n  getSessionId,\n  getTokenUsage,\n  parseTimestampToNs,\n  extractTextFromContent,\n  findLastUserPrompt,\n  buildToolResultMap,\n} from '../../src/transcript';\nimport type { RolloutLine } from '../../src/types';\n\nbeforeEach(() => (spans.length = 0));\n\ntest('parseTimestampToNs', () => {\n  expect(parseTimestampToNs(null)).toBeNull();\n  expect(parseTimestampToNs('')).toBeNull();\n  expect(parseTimestampToNs(undefined)).toBeNull();\n  const ns = parseTimestampToNs('2026-07-06T00:00:00.000Z');\n  expect(ns).toBeGreaterThan(0);\n  expect(ns).toBe(Date.parse('2026-07-06T00:00:00.000Z') * 1e6);\n});\n\ntest('extractTextFromContent', () => {\n  expect(extractTextFromContent(undefined)).toBe('');\n  expect(extractTextFromContent('hi')).toBe('hi');\n  expect(\n    extractTextFromContent([\n      { type: 'input_text', text: 'a' },\n      { type: 'input_text', text: 'b' },\n    ]),\n  ).toBe('a\\nb');\n});\n\ntest('processNotify empty -> no spans, no flush', async () => {\n  await processNotify({\n    type: 'agent-turn-complete',\n    'thread-id': 't1',\n    'turn-id': 'x',\n    cwd: '/',\n    client: 'c',\n    'input-messages': [],\n    'last-assistant-message': 'done',\n  });\n  expect(spans.length).toBe(0);\n  expect((core.flushTraces as jest.Mock)).not.toHaveBeenCalled();\n});\n\ntest('processNotify creates root + llm', async () => {\n  await processNotify({\n    type: 'agent-turn-complete',\n    'thread-id': 'thread-42',\n    'turn-id': 'x',\n    cwd: '/',\n    client: 'c',\n    'input-messages': ['first', 'last input'],\n    'last-assistant-message': 'the answer',\n  });\n  const root = spans[0];\n  const llm = spans[1];\n  expect(root.opts.name).toBe('codex_conversation');\n  expect(root.opts.spanType).toBe('AGENT');\n  expect(root.opts.inputs).toBe('last input');\n  expect(root.outputs).toBe('the answer');\n  expect(llm.opts.name).toBe('llm_call');\n  expect(llm.opts.parent).toBe(root);\n  expect(llm.opts.inputs).toEqual({ model: 'unknown', messages: [{ role: 'user', content: 'last input' }] });\n  expect(llm.outputs).toEqual({ choices: [{ message: { role: 'assistant', content: 'the answer' } }] });\n  const meta = (core as any).__trace.info.traceMetadata;\n  expect(meta['mlflow.trace.session']).toBe('thread-42');\n  expect(meta['mlflow.trace.user']).toBeDefined();\n  expect((core.flushTraces as jest.Mock)).toHaveBeenCalled();\n});\n\nconst ts = (s: number) => `2026-07-06T00:00:0${s}.000Z`;\n\nconst turn: RolloutLine[] = [\n  { timestamp: ts(0), type: 'event_msg', payload: { type: 'task_started' } },\n  { timestamp: ts(1), type: 'response_item', payload: { type: 'message', role: 'user', content: [{ type: 'input_text', text: 'hi' }] } },\n  { timestamp: ts(2), type: 'response_item', payload: { type: 'function_call', name: 'shell', call_id: 'c1', arguments: '{\"cmd\":\"ls\"}' } },\n  { timestamp: ts(3), type: 'response_item', payload: { type: 'function_call_output', call_id: 'c1', output: 'file.txt' } },\n  { timestamp: ts(4), type: 'event_msg', payload: { type: 'exec_command_end', call_id: 'c1', exit_code: 0, status: 'success' } },\n  { timestamp: ts(5), type: 'response_item', payload: { type: 'message', role: 'assistant', content: [{ type: 'output_text', text: 'here' }] } },\n  { timestamp: ts(6), type: 'response_item', payload: { type: 'function_call', name: 'shell', call_id: 'c2', arguments: '{\"cmd\":\"boom\"}' } },\n  { timestamp: ts(7), type: 'response_item', payload: { type: 'function_call_output', call_id: 'c2', output: 'err' } },\n  { timestamp: ts(8), type: 'event_msg', payload: { type: 'exec_command_end', call_id: 'c2', exit_code: 2, status: 'failed' } },\n  { timestamp: ts(9), type: 'response_item', payload: { type: 'message', role: 'assistant', content: [{ type: 'output_text', text: 'final' }] } },\n  { timestamp: ts(9), type: 'event_msg', payload: { type: 'task_complete' } },\n];\n\ntest('createChildSpans timing/status', () => {\n  createChildSpans({ spanId: 'root' } as any, turn, 'gpt-5');\n  const names = spans.map((s) => s.opts.name);\n  expect(names).toEqual(['tool_shell', 'llm_call', 'tool_shell', 'llm_call']);\n\n  const tool1 = spans[0];\n  expect(tool1.opts.spanType).toBe('TOOL');\n  expect(tool1.opts.inputs).toEqual({ cmd: 'ls' });\n  expect(tool1.opts.attributes).toEqual({ tool_name: 'shell', tool_id: 'c1' });\n  expect(tool1.outputs).toEqual({ result: 'file.txt' });\n  expect(tool1.opts.startTimeNs).toBe(parseTimestampToNs(ts(2)));\n  expect(tool1.endArgs.endTimeNs).toBe(parseTimestampToNs(ts(3)));\n  expect(tool1.status).toBeUndefined(); // success -> no setStatus\n\n  const llm1 = spans[1];\n  expect(llm1.opts.startTimeNs).toBe(parseTimestampToNs(ts(0))); // first llm = task_started\n  expect(llm1.endArgs.endTimeNs).toBe(parseTimestampToNs(ts(5)));\n  expect(llm1.opts.inputs.model).toBe('gpt-5');\n  expect(llm1.outputs).toEqual({ choices: [{ message: { role: 'assistant', content: 'here' } }] });\n\n  const tool2 = spans[2];\n  expect(tool2.status).toEqual({ code: 'STATUS_CODE_ERROR', msg: expect.stringContaining('2') });\n\n  const llm2 = spans[3];\n  expect(llm2.opts.startTimeNs).toBe(parseTimestampToNs(ts(7))); // preceding function_call_output\n  expect(llm2.endArgs.endTimeNs).toBe(parseTimestampToNs(ts(9)));\n});\n\ntest('getLastTurnRecords / model / session / tokens / prompt / resultmap', () => {\n  const full: RolloutLine[] = [\n    { timestamp: ts(0), type: 'session_meta', payload: { type: 'session_meta', id: 'sess-1', model: 'gpt-5-codex' } },\n    ...turn,\n    { timestamp: ts(9), type: 'event_msg', payload: { type: 'token_count', info: { total_token_usage: { input_tokens: 10, output_tokens: 5, total_tokens: 15 } } } },\n  ];\n  const lastTurn = getLastTurnRecords(full);\n  expect(lastTurn[0].type).toBe('event_msg');\n  expect(lastTurn[0].payload.type).toBe('task_started');\n  expect(lastTurn[lastTurn.length - 1].payload.type).toBe('task_complete');\n  expect(getModel(full)).toBe('gpt-5-codex');\n  expect(getSessionId(full)).toBe('sess-1');\n  expect(getTokenUsage(full)).toEqual({ input_tokens: 10, output_tokens: 5, total_tokens: 15 });\n  expect(getModel([])).toBe('unknown');\n  expect(findLastUserPrompt(full)).toEqual({ text: 'hi' });\n  expect(buildToolResultMap(full)).toEqual({ c1: 'file.txt', c2: 'err' });\n});\n"],"version":3}
