 extractTextFromContent, parseTimestampToNs, coerceOutput } from './transcript';\nimport type { ChatMessage, NotifyPayload, RolloutLine } from './types';\n\n// Only initialize the SDK once per process.\nlet initialized = false;\n\n/**\n * Best-effort initialization of the MLflow SDK from environment variables.\n * Never throws; span creation proceeds regardless so that unit tests (which\n * mock `@mlflow/core`) and real usage share the same code path.\n */\nfunction ensureInitialized(): void {\n  if (initialized) {\n    return;\n  }\n\n  const trackingUri = process.env.MLFLOW_TRACKING_URI;\n  const experimentId = process.env.MLFLOW_EXPERIMENT_ID;\n  if (!trackingUri || !experimentId) {\n    return;\n  }\n\n  try {\n    init({ trackingUri, experimentId });\n    initialized = true;\n  } catch {\n    // Initialization is best-effort; ignore failures.\n  }\n}\n\n/**\n * Return the nanosecond timestamp of the turn's `task_started` event.\n *\n * @param turn Records belonging to a single turn.\n * @returns The timestamp in nanoseconds, or null if no task_started exists.\n */\nexport function findTaskStartedNs(turn: RolloutLine[]): number | null {\n  for (const line of turn) {\n    if (line.type === 'event_msg' && line.payload?.type === 'task_started') {\n      return parseTimestampToNs(line.timestamp);\n    }\n  }\n  return null;\n}\n\n/**\n * Return the nanosecond timestamp of the turn's `task_complete` event.\n *\n * @param turn Records belonging to a single turn.\n * @returns The timestamp in nanoseconds, or null if no task_complete exists.\n */\nexport function findTaskCompleteNs(turn: RolloutLine[]): number | null {\n  for (const line of turn) {\n    if (line.type === 'event_msg' && line.payload?.type === 'task_complete') {\n      return parseTimestampToNs(line.timestamp);\n    }\n  }\n  return null;\n}\n\n/**\n * Scan `exec_command_end` events and build a map of tool execution statuses.\n *\n * @param turn Records belonging to a single turn.\n * @returns A map from call_id to { failed, exitCode }.\n */\nexport function buildToolStatuses(\n  turn: RolloutLine[],\n): Record<string, { failed: boolean; exitCode: number }> {\n  const statuses: Record<string, { failed: boolean; exitCode: number }> = {};\n  for (const line of turn) {\n    if (line.type === 'event_msg' && line.payload?.type === 'exec_command_end') {\n      const { payload } = line;\n      const callId = payload.call_id;\n      if (callId == null) {\n        continue;\n      }\n      const exitCode = Number(payload.exit_code ?? 0);\n      const failed = payload.status === 'failed' || exitCode !== 0;\n      statuses[callId] = { failed, exitCode };\n    }\n  }\n  return statuses;\n}\n\n/**\n * Reconstruct OpenAI chat-format messages from a slice of the transcript.\n *\n * Records are converted up to (but not including) `uptoIndex`:\n *  - user/assistant/developer messages -> { role, content } (developer -> system)\n *  - function_call -> assistant message with a `tool_calls` entry\n *  - function_call_output -> tool message\n *\n * Text messages whose extracted text is empty or whitespace-only are skipped.\n *\n * @param items The turn (or full transcript) records.\n * @param uptoIndex Exclusive upper bound on the records to include.\n * @returns The reconstructed conversation history.\n */\nexport function reconstructMessages(items: RolloutLine[], uptoIndex: number): ChatMessage[] {\n  const messages: ChatMessage[] = [];\n  const end = Math.min(uptoIndex, items.length);\n\n  for (let i = 0; i < end; i++) {\n    const item = items[i];\n    if (item.type !== 'response_item') {\n      continue;\n    }\n    const { payload } = item;\n\n    if (payload.type === 'function_call') {\n      messages.push({\n        role: 'assistant',\n        content: null,\n        tool_calls: [\n          {\n            id: payload.call_id ?? '',\n            type: 'function',\n            function: {\n              name: payload.name ?? '',\n              arguments: payload.arguments ?? '',\n            },\n          },\n        ],\n      });\n    } else if (payload.type === 'function_call_output') {\n      messages.push({\n        role: 'tool',\n        tool_call_id: payload.call_id ?? '',\n        content: coerceOutput(payload.output),\n      });\n    } else if (\n      payload.role === 'user' ||\n      payload.role === 'assistant' ||\n      payload.role === 'developer'\n    ) {\n      const text = extractTextFromContent(payload.content);\n      if (text.trim() === '') {\n        continue;\n      }\n      messages.push({\n        role: payload.role === 'developer' ? 'system' : payload.role,\n        content: text,\n      });\n    }\n  }\n\n  return messages;\n}\n\n/**\n * Create LLM and TOOL child spans for a completed turn.\n *\n * One LLM span (`llm_call`) is created per assistant message and one TOOL span\n * (`tool_<function_name>`) per function_call. All spans are parented to\n * `parent`. Timestamps are derived from the surrounding transcript records.\n *\n * @param parent The parent span (root conversation span).\n * @param turn Records belonging to a single turn.\n * @param model The model name to record on LLM spans.\n */\nexport function createChildSpans(\n  parent: { spanId: string },\n  turn: RolloutLine[],\n  model: string,\n): void {\n  const taskStartedNs = findTaskStartedNs(turn);\n  const toolStatuses = buildToolStatuses(turn);\n\n  // Precompute the timestamp and output for each tool call's output record.\n  const outputByCallId: Record<string, { ns: number | null; output: string }> = {};\n  for (const line of turn) {\n    if (\n      line.type === 'response_item' &&\n      line.payload?.type === 'function_call_output' &&\n      line.payload.call_id != null\n    ) {\n      outputByCallId[line.payload.call_id] = {\n        ns: parseTimestampToNs(line.timestamp),\n        output: coerceOutput(line.payload.output),\n      };\n    }\n  }\n\n  let firstLlm = true;\n  let lastToolOutputNs: number | null = null;\n\n  for (let i = 0; i < turn.length; i++) {\n    const line = turn[i];\n    if (line.type !== 'response_item') {\n      continue;\n    }\n    const { payload } = line;\n\n    if (payload.type === 'message' && payload.role === 'assistant') {\n      const startNs = firstLlm ? taskStartedNs : lastToolOutputNs;\n      const endNs = parseTimestampToNs(line.timestamp);\n      const content = extractTextFromContent(payload.content);\n      const messages = reconstructMessages(turn, i);\n\n      const span = startSpan({\n        name: 'llm_call',\n        parent: parent as unknown as LiveSpan,\n        spanType: SpanType.LLM,\n        startTimeNs: startNs ?? undefined,\n        inputs: { model, messages },\n      });\n      span.setOutputs({ choices: [{ message: { role: 'assistant', content } }] });\n      span.end({ endTimeNs: endNs ?? undefined });\n\n      firstLlm = false;\n    } else if (payload.type === 'function_call') {\n      const callId = payload.call_id ?? '';\n      const functionName = payload.name ?? 'unknown';\n      const startNs = parseTimestampToNs(line.timestamp);\n      const matched = outputByCallId[callId];\n      const endNs = matched?.ns ?? null;\n      const result = matched?.output ?? '';\n\n      let args: unknown = {};\n      if (payload.arguments) {\n        try {\n          args = JSON.parse(payload.arguments);\n        } catch {\n          args = {};\n        }\n      }\n\n      const span = startSpan({\n        name: `tool_${functionName}`,\n        parent: parent as unknown as LiveSpan,\n        spanType: SpanType.TOOL,\n        startTimeNs: startNs ?? undefined,\n        inputs: args,\n        attributes: { tool_name: functionName, tool_id: callId },\n      });\n      span.setOutputs({ result });\n\n      const status = toolStatuses[callId];\n      if (status && status.failed) {\n        span.setStatus(SpanStatusCode.ERROR, `Tool call failed with exit code ${status.exitCode}`);\n      }\n\n      span.end({ endTimeNs: endNs ?? undefined });\n    } else if (payload.type === 'function_call_output') {\n      lastToolOutputNs = parseTimestampToNs(line.timestamp);\n    }\n  }\n}\n\n/**\n * Process an `agent-turn-complete` notification and create MLflow spans.\n *\n * Creates an AGENT root span (`codex_conversation`) whose inputs are the last\n * input message (raw string) and whose outputs are the last assistant message\n * (raw string), plus a single LLM child span (`llm_call`). Skips all processing\n * when there are no input messages.\n *\n * @param payload The Codex notification payload.\n */\nexport async function processNotify(payload: NotifyPayload): Promise<void> {\n  const inputMessages = payload['input-messages'];\n  if (!inputMessages || inputMessages.length === 0) {\n    return;\n  }\n\n  ensureInitialized();\n\n  const lastInput = inputMessages[inputMessages.length - 1];\n  const lastAssistant = payload['last-assistant-message'];\n\n  const root = startSpan({\n    name: 'codex_conversation',\n    spanType: SpanType.AGENT,\n    inputs: lastInput,\n  });\n\n  const llmSpan = startSpan({\n    name: 'llm_call',\n    parent: root,\n    spanType: SpanType.LLM,\n    inputs: {\n      model: 'unknown',\n      messages: [{ role: 'user', content: lastInput }],\n    },\n  });\n  llmSpan.setOutputs({\n    choices: [{ message: { role: 'assistant', content: lastAssistant } }],\n  });\n  llmSpan.end();\n\n  root.setOutputs(lastAssistant);\n\n  // Attach session/user metadata to the trace before it is flushed.\n  try {\n    const trace = InMemoryTraceManager.getInstance().getTrace(root.traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        [TraceMetadataKey.TRACE_SESSION]: payload['thread-id'],\n        [TraceMetadataKey.TRACE_USER]: process.env.USER ?? 'codex',\n      };\n    }\n  } catch {\n    // Metadata is best-effort; ignore failures.\n  }\n\n  root.end();\n\n  await flushTraces();\n}\n"],"version":3}
